const ignoredTitlePatterns = [
  /-dev-/i,
  /\bdev build\b/i,
  /\bsnapshot\b/i
];

return items.filter(item => {
  const title = item.json.title || "";

  const isIgnored = ignoredTitlePatterns.some(
    pattern => pattern.test(title)
  );

  return !isIgnored;
});

const now = new Date();

// Keep items from the last 7 days
const cutoff = new Date(
  now.getTime() - (7 * 24 * 60 * 60 * 1000)
);

const dateValues = [
  "isoDate",
  "pubDate",
  "pubdate",
  "published",
  "updated",
  "created"
];

return items.filter(item => {
  const data = item.json;

  const dateField = dateValues.find(
    field => data[field]
  );

  if (!dateField) {
    // Keep for now so we can inspect feeds
    return true;
  }

  const publishedDate = new Date(data[dateField]);

  return publishedDate >= cutoff;
});

const ignoredTitlePatterns = [
  /\bchore\b/i,
  /\btest\b/i,
  /\btests\b/i,
  /\btesting\b/i,
  /\bdocumentation\b/i,
  /\bdocs\b/i,
  /\btranslation\b/i,
  /\btranslations\b/i,
  /\btypo\b/i,
  /\bmerge\b/i,
  /\bmerged\b/i,
  /\brefactor\b/i,
  /\bcleanup\b/i
];

return items.filter(item => {
  const title = item.json.title || "";

  const isIgnored = ignoredTitlePatterns.some(
    pattern => pattern.test(title)
  );

  return !isIgnored;
});

return items.map(item => {
  const data = item.json;

  return {
    json: {
      title: data.title || "Untitled release",

      link:
        data.link ||
        data.guid ||
        data.url ||
        "#",

      summary:
        data.contentSnippet ||
        data.description ||
        data.content ||
        "",

      published:
        data.isoDate ||
        data.pubDate ||
        data.published ||
        null,

      meta: {
        ...(data.meta || {})
      }
    }
  };
});

const groups = {};

for (const item of items) {
  const category =
    item.json.meta?.category || "Other";

  if (!groups[category]) {
    groups[category] = [];
  }

  groups[category].push(item.json);
}

return [
  {
    json: {
      groups
    }
  }
];

const groups = items[0].json.groups;

const MAX_SUMMARY_LENGTH = 250;

function truncate(text, maxLength) {
  if (!text) return "";

  // Strip HTML tags from RSS summaries
  const clean = text.replace(/<[^>]*>/g, "").trim();

  if (clean.length <= maxLength) {
    return clean;
  }

  return clean.substring(0, maxLength).trim() + "...";
}

