for (const [category, releases] of Object.entries(groups)) {

  html += `
  <h2 style="
    color:#D97757;
    font-size:20px;
    margin-top:32px;
    margin-bottom:16px;
  ">
    ${category}
  </h2>
  `;

  for (const release of releases.slice(0, 5)) {

    html += `
    <div style="
      background:#FAF9F5;
      border-radius:12px;
      padding:16px;
      margin-bottom:16px;
    ">

      <h3 style="
        margin:0 0 8px 0;
        font-size:16px;
        color:#1C1B19;
      ">
        ${release.title}
      </h3>

      <p style="
        margin:0 0 12px 0;
        color:#4B4540;
        font-size:14px;
        line-height:1.5;
      ">
        ${truncate(release.summary, MAX_SUMMARY_LENGTH)}
      </p>

      <p style="
        margin:0;
        font-size:13px;
        color:#8A8178;
      ">
        ${release.meta.source}
      </p>

      <a href="${release.link}" style="
        display:inline-block;
        margin-top:12px;
        padding:8px 14px;
        background:#D97757;
        color:#FFFFFF;
        text-decoration:none;
        border-radius:8px;
        font-size:14px;
      ">
        Read More →
      </a>

    </div>
    `;
  }
}

html += `
</td>
</tr>

</table>

</td>
</tr>
</table>

</body>
</html>
`;

return [
  {
    json: {
      html,
      hasReleases: Object.values(groups).some(
        releases => releases.length > 0
      )
    }
  }
];

